Contract ManageSupplierCRUDService::createSupplier(id:Integer,name:String): Boolean {
          definition:
          supplier:Supplier = Supplier.allInstance()->any(s | s.Id = id)


            postcondition:
          if supplier.oclIsUndefined() then let newSupplier:Supplier in newSupplier.oclIsNew() and Supplier.allInstance()->includes(newSupplier) and newSupplier.Id = id and newSupplier.Name = name and result = true else result = false endif

        }
